<?php
declare(strict_types=1);
$https = (!empty($_SERVER['HTTPS']) && $_SERVER['HTTPS'] !== 'off') || (($_SERVER['HTTP_X_FORWARDED_PROTO'] ?? '') === 'https');
$scheme = $https ? 'https' : 'http';
$host = preg_replace('/[^a-zA-Z0-9.:-]/', '', (string)($_SERVER['HTTP_HOST'] ?? 'localhost')) ?: 'localhost';
$path = rtrim(str_replace('\\', '/', dirname((string)($_SERVER['SCRIPT_NAME'] ?? '/qr.php'))), '/');
$target = $scheme . '://' . $host . ($path === '' ? '' : $path) . '/';
?>
<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#111827"><title>Walkie-Talkie QR Code</title>
<style>body{font-family:system-ui,-apple-system,sans-serif;background:#0b1220;color:#eef3ff;min-height:100vh;display:grid;place-items:center;margin:0;padding:24px;box-sizing:border-box}.card{max-width:520px;width:100%;box-sizing:border-box;background:#141e31;border:1px solid #2b3954;border-radius:24px;padding:28px;text-align:center;box-shadow:0 18px 60px #0004}h1{margin:0 0 8px;font-size:1.8rem}p{color:#b7c3d9;line-height:1.5}#qrcode{background:white;padding:16px;border-radius:16px;display:inline-block;margin:16px auto;min-height:220px;min-width:220px}#qrcode img{display:block;max-width:100%;height:auto}a{color:#8bd5ff;overflow-wrap:anywhere}.button{display:inline-block;background:#56dfaa;color:#07150f;text-decoration:none;font-weight:700;padding:12px 18px;border-radius:12px;margin:8px 4px;border:0;cursor:pointer}.note{font-size:.9rem}</style></head><body><main class="card"><h1>Walkie-Talkie</h1><p>Scan this QR code with your phone to open the join page.</p><div id="qrcode" aria-label="QR code"></div><p><a id="target-link" href="<?= htmlspecialchars($target, ENT_QUOTES, 'UTF-8') ?>"><?= htmlspecialchars($target, ENT_QUOTES, 'UTF-8') ?></a></p><p class="note">Keep this page open on your computer while scanning, or print it for your team.</p><a class="button" href="<?= htmlspecialchars($target, ENT_QUOTES, 'UTF-8') ?>">Open Walkie-Talkie</a><button class="button" onclick="window.print()">Print QR</button><p class="note">Voice needs HTTPS, microphone permission, and a working WebRTC network connection.</p></main>
<script src="https://cdnjs.cloudflare.com/ajax/libs/qrcodejs/1.0.0/qrcode.min.js"></script><script>const target=<?= json_encode($target, JSON_HEX_TAG|JSON_HEX_APOS|JSON_HEX_AMP|JSON_HEX_QUOT) ?>;if(window.QRCode){new QRCode(document.getElementById('qrcode'),{text:target,width:220,height:220,colorDark:'#000000',colorLight:'#ffffff',correctLevel:QRCode.CorrectLevel.M});}else{document.getElementById('qrcode').textContent='QR library did not load. Open the link below instead.'}</script></body></html>
